function solve(s) {
  const v = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  let total = 0, maxSeen = 0;
  for (let i = s.length - 1; i >= 0; i--) {
    if (v[s[i]] >= maxSeen) { total += v[s[i]]; maxSeen = v[s[i]]; }
    else total -= v[s[i]];
  }
  return total;
}

function solve(s) {
  const v = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    const cur = v[s[i]], next = v[s[i + 1]] || 0;
    if (cur < next) total -= cur;
    else total += cur;
  }
  return total;
}

